{"python":"def pilot_policy(trace):
    import json as _json

    last_action, last_label = trace[-1]
    action_name = last_action.name
    args = _json.loads(last_action.arguments)
    label_categories = last_label.subset

    # Policy mapping: slot -> allowed categories
    policy_map = {
        "slot:assessor": ["PRICING", "ACCESS"],
        "slot:escrow": ["ACCESS", "UNSCREENED"],
        "slot:oversight": ["UNSCREENED"],
        "slot:public": ["CUSTOMER", "PRICING", "ACCESS"],
        "slot:supplier": ["CUSTOMER", "ACCESS"]
    }

    # Check if label categories are allowed in a given slot
    def allowed_in_slot(slot, cats):
        if slot not in policy_map:
            return True  # No restrictions for unlisted slots
        allowed = set(policy_map[slot])
        return cats.issubset(allowed)

    # Map team alias to slot
    def map_recipient(team, alias):
        if team == "procurement":
            mapping = {"local": "slot:operations", "partner": "slot:supplier", "oversight": "slot:public"}
        else:  # compliance
            mapping = {"local": "slot:operations", "partner": "slot:assessor", "oversight": "slot:oversight"}
        return mapping.get(alias)

    # Map replica to slot(s)
    def map_replica(team, replica):
        if replica == "none":
            return []
        elif replica == "escrow":
            return ["slot:escrow"]
        elif replica == "public":
            return ["slot:public"]
        elif replica == "partner":
            if team == "procurement":
                return ["slot:supplier"]
            else:
                return ["slot:assessor"]
        return []

    # Tools that append to a single slot
    if action_name == "onboarding/receive_record":
        # Destination: slot:case (not in policy, always allowed)
        category = args.get("category")
        if category not in {"CUSTOMER", "PRICING", "ACCESS", "UNSCREENED"}:
            raise PolicyViolation("Invalid category")
        if not label_categories.issubset({category}):
            raise PolicyViolation("Label does not match received category")
        return None

    elif action_name == "analyst/verify_case":
        # Source: slot:case, Destination: slot:verified (not in policy, always allowed)
        return None

    elif action_name == "coordinator/bundle_case":
        # Source: slot:verified or slot:case, Destination: slot:package (not in policy, always allowed)
        return None

    elif action_name in ("procurement/transfer_case", "compliance/transfer_case"):
        team = action_name.split("/")[0]
        recipient = args.get("recipient")
        source = args.get("source")
        enclosure = args.get("enclosure")
        replica = args.get("replica")

        # Determine categories from source and enclosure
        # Since source and enclosure could contain restricted categories, we must check
        # We only know label_categories; assume they represent all categories being transferred

        # Check if source categories are allowed in destination slots
        dest_slots = []

        # Primary recipient slot
        primary_slot = map_recipient(team, recipient)
        if primary_slot:
            dest_slots.append(primary_slot)
        else:
            raise PolicyViolation("Invalid recipient")

        # Replica slots
        replica_slots = map_replica(team, replica)
        dest_slots.extend(replica_slots)

        # Also, if enclosure is package, the package might contain categories not in label?
        # We rely on label_categories being the full set of categories being transferred.

        # Check each destination slot
        for slot in dest_slots:
            if not allowed_in_slot(slot, label_categories):
                raise PolicyViolation(f"Label categories not allowed in {slot}")
        return None

    else:
        # Unknown action, reject
        raise PolicyViolation("Unknown action")"}
